def gf2_fit_predict(train_x,train_y,test_x):
 # train rows lists of 0/1 features; return one solution via RREF, None if inconsistent
 m=len(train_x);n=len(train_x[0]); piv={}
 for x,y in zip(train_x,train_y):
  v=sum(int(z)<<i for i,z in enumerate(x)); yy=int(y)
  while v:
   i=v.bit_length()-1
   if i in piv:v^=piv[i][0];yy^=piv[i][1]
   else:piv[i]=(v,yy);break
  if not v and yy:return None
 # free variables zero; back solve in pivot insertion order high to low
 sol=0
 for i in sorted(piv):
  v,y=piv[i]
  # all vars above pivot already set (higher pivots may nonzero)
  bit=y ^ ((v & sol).bit_count()%2)
  if bit:sol|=1<<i
 out=[]
 for x in test_x:out.append((sum(int(z)<<i for i,z in enumerate(x)) & sol).bit_count()%2)
 return out

